def transform(grid):
    h, w = len(grid), len(grid[0])
    counts = {value: sum(row.count(value) for row in grid) for value in {v for row in grid for v in row}}
    background = max(counts, key=counts.get)
    colors = [value for value in counts if value != background]
    if not colors:
        return [row[:] for row in grid]
    color = colors[0]
    points = [(r, c) for r in range(h) for c in range(w) if grid[r][c] == color]
    r0 = min(r for r, c in points)
    r1 = max(r for r, c in points)
    c0 = min(c for r, c in points)
    c1 = max(c for r, c in points)
    out = [row[:] for row in grid]
    for r in range(r0, r1 + 1):
        for c in range(c0, c1 + 1):
            if (r in (r0, r1) or c in (c0, c1)) and grid[r][c] == background:
                out[r][c] = 2
    for r in range(h):
        positions = [c for c in range(w) if grid[r][c] == color]
        if len(positions) >= 4:
            for a, b in zip(positions, positions[1:]):
                for c in range(a + 1, b):
                    if grid[r][c] == background:
                        out[r][c] = 2
    for c in range(w):
        positions = [r for r in range(h) if grid[r][c] == color]
        if len(positions) >= 4:
            for a, b in zip(positions, positions[1:]):
                for r in range(a + 1, b):
                    if grid[r][c] == background:
                        out[r][c] = 2
    return out
